func solvePuzzle(board, goal) = {
  local queue = [[board, 0]]
  local visited = [board.join(",")]
  local result = -1
  local found = false
  while (queue.listLen() > 0 && !found) {
    local cur = queue[1]
    queue.remove(1)
    local state = cur[1]
    local moves = cur[2]
    local flat = state.join(",")
    local gflat = goal.join(",")
    if (flat === gflat) {
      result = moves
      found = true
    } else {
      local zeroIdx = 1
      for (i: 1 .. state.listLen()) {
        if (state[i] == 0) {
          zeroIdx = i
        }
      }
      local neighbors = []
      if (zeroIdx > 3) { neighbors.add(zeroIdx - 3) }
      if (zeroIdx <= 6) { neighbors.add(zeroIdx + 3) }
      if ((zeroIdx - 1) % 3 != 0) { neighbors.add(zeroIdx - 1) }
      if (zeroIdx % 3 != 0) { neighbors.add(zeroIdx + 1) }
      for (ni in neighbors) {
        local ns = copyList(state)
        local tmp = ns[zeroIdx]
        ns[zeroIdx] = ns[ni]
        ns[ni] = tmp
        local key = ns.join(",")
        if (!visited.containsItem(key)) {
          visited.add(key)
          queue.add([ns, moves + 1])
        }
      }
    }
  }
  result
}
