func wildcard_match(pattern, text) = {
  local p = pattern.textLen()
  local t = text.textLen()
  func match(pi, ti) = {
    if (pi > p && ti > t) {
      true
    } else if (pi > p) {
      false
    } else if (pattern.segment(pi, 1) === "*") {
      if (pi == p) {
        true
      } else {
        match(pi + 1, ti) || if (ti <= t) match(pi, ti + 1) else false
      }
    } else if (ti > t) {
      false
    } else {
      local pc = pattern.segment(pi, 1)
      local tc = text.segment(ti, 1)
      if (pc === "?" || pc === tc) {
        match(pi + 1, ti + 1)
      } else {
        false
      }
    }
  }
  match(1, 1)
}
